/// The class that declares `interactLivingEntity` for an item.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ItemInteractLivingEntity {
    /// The base-class default.
    Default,
    DyeItem,
    NameTagItem,
}

pub fn item_interact_living_entity(kind: ItemKind) -> ItemInteractLivingEntity {
    use ItemKind::*;
    match kind {
        BlackDye | BlueDye | BrownDye | CyanDye | GrayDye | GreenDye | LightBlueDye
        | LightGrayDye | LimeDye | MagentaDye | OrangeDye | PinkDye | PurpleDye | RedDye
        | WhiteDye | YellowDye => ItemInteractLivingEntity::DyeItem,
        NameTag => ItemInteractLivingEntity::NameTagItem,
        _ => ItemInteractLivingEntity::Default,
    }
}

