/// The class that overrides `interact` for an entity (`Entity` and `Mob` are
/// the defaults).
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum EntityInteract {
    /// The base-class default.
    Default,
    AbstractBoat,
    AbstractChestBoat,
    AbstractMinecartContainer,
    AbstractNautilus,
    ArmorStand,
    CamelHusk,
    Interaction,
    ItemFrame,
    LeashFenceKnotEntity,
    Minecart,
    MinecartChest,
    MinecartCommandBlock,
    MinecartFurnace,
    ZombieHorse,
}

pub fn entity_interact(kind: EntityKind) -> EntityInteract {
    use EntityKind::*;
    match kind {
        AcaciaBoat | BambooRaft | BirchBoat | CherryBoat | DarkOakBoat | JungleBoat
        | MangroveBoat | OakBoat | PaleOakBoat | SpruceBoat => EntityInteract::AbstractBoat,
        AcaciaChestBoat | BambooChestRaft | BirchChestBoat | CherryChestBoat | DarkOakChestBoat
        | JungleChestBoat | MangroveChestBoat | OakChestBoat | PaleOakChestBoat
        | SpruceChestBoat => EntityInteract::AbstractChestBoat,
        HopperMinecart => EntityInteract::AbstractMinecartContainer,
        Nautilus | ZombieNautilus => EntityInteract::AbstractNautilus,
        ArmorStand => EntityInteract::ArmorStand,
        CamelHusk => EntityInteract::CamelHusk,
        Interaction => EntityInteract::Interaction,
        GlowItemFrame | ItemFrame => EntityInteract::ItemFrame,
        LeashKnot => EntityInteract::LeashFenceKnotEntity,
        Minecart => EntityInteract::Minecart,
        ChestMinecart => EntityInteract::MinecartChest,
        CommandBlockMinecart => EntityInteract::MinecartCommandBlock,
        FurnaceMinecart => EntityInteract::MinecartFurnace,
        ZombieHorse => EntityInteract::ZombieHorse,
        _ => EntityInteract::Default,
    }
}

